import { BrowserRouter, Routes, Route, NavLink, Link, Outlet } from 'react-router';

function Layout() {
  return (
    <div>
      <header>
        <strong>Toko Budi</strong>
        <nav>
          <NavLink to="/">Beranda</NavLink> | <NavLink to="/produk">Produk</NavLink> | <NavLink to="/promo-lama">Promo lama</NavLink>
        </nav>
      </header>
      <main>
        <Outlet />
      </main>
      <footer>© Toko Budi</footer>
    </div>
  );
}

function Beranda() {
  return <p>Selamat datang!</p>;
}

function Produk() {
  return <p>Kopi Susu, Teh Melati, Roti Bakar</p>;
}

function TidakDitemukan() {
  return (
    <div>
      <h2>Halaman tidak ditemukan</h2>
      <Link to="/">Kembali ke beranda</Link>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<Layout />}>
          <Route path="/" element={<Beranda />} />
          <Route path="/produk" element={<Produk />} />
          <Route path="*" element={<TidakDitemukan />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

